//! Reads geometry generated by the user's PE32 SpeedTreeRT DLL. No SPT approximation.
use crate::{pck, scene};
use std::{
    collections::HashMap,
    fs::{self, File},
    io::Read,
    path::Path,
    sync::atomic::{AtomicUsize, Ordering},
};
#[derive(Clone)]
pub struct Vert {
    pub pos: [f32; 3],
    pub normal: [f32; 3],
    pub uv: [f32; 2],
}
#[derive(Default)]
pub struct Part {
    pub vertices: Vec<Vert>,
    pub indices: Vec<u32>,
}
pub struct Leaf {
    pub center: [f32; 3],
    // PWTREE09 records the per-leaf runtime normal used by the client.
    // Older caches do not contain normals and retain the legacy fallback.
    pub normal: Option<[f32; 3]>,
    pub rho: f32,
    pub corners: [[f32; 3]; 4],
    pub uv: [[f32; 2]; 4],
    pub cluster: u32,
}
pub struct TreeLod {
    pub branch: Part,
    pub frond: Part,
    /// Native SpeedTree alpha-test references (0..255), present in PWTREE08.
    /// Older caches retain `None` so the renderer can preserve its legacy cutout.
    pub branch_alpha_ref: Option<f32>,
    pub frond_alpha_ref: Option<f32>,
    pub leaves: Vec<Leaf>,
    // Each cluster/corner has 64 runtime samples, stored in local camera space.
    pub rocking: Vec<[f32; 3]>,
    pub rocking_clusters: usize,
}
pub struct TreeMesh {
    pub lods: Vec<TreeLod>,
    pub bark: image::RgbaImage,
    pub composite: image::RgbaImage,
    /// Authored lower mip levels (1..N) retained for the opt-in P4.07 path.
    /// Empty when the source chain is unavailable; the default path ignores them.
    pub bark_mips: Vec<image::RgbaImage>,
    pub composite_mips: Vec<image::RgbaImage>,
}
pub struct Trees {
    pub types: Vec<Option<TreeMesh>>,
    pub placements: Vec<scene::Tree>,
    /// Why trees are not drawn, in words the UI can show verbatim.
    ///
    /// `None` means trees loaded (or the map authors none). `Some` names the
    /// actual cause -- no cache, no DLL, no `trees.pck`, or missing names --
    /// because "trees are off" with no reason is a bug report nobody can act
    /// on. The same sentence goes to the log and to the World panel.
    pub off_reason: Option<String>,
}
struct Reader<'a> {
    d: &'a [u8],
    p: usize,
}
impl<'a> Reader<'a> {
    fn take(&mut self, n: usize) -> Result<&'a [u8], String> {
        let e = self.p.checked_add(n).ok_or("tree offset overflow")?;
        let s = self.d.get(self.p..e).ok_or("truncated tree cache")?;
        self.p = e;
        Ok(s)
    }
    fn u(&mut self) -> Result<u32, String> {
        Ok(u32::from_le_bytes(self.take(4)?.try_into().unwrap()))
    }
    fn f(&mut self) -> Result<f32, String> {
        let f = f32::from_bits(self.u()?);
        if !f.is_finite() {
            return Err("non-finite tree data".into());
        }
        Ok(f)
    }
    fn vec3(&mut self) -> Result<[f32; 3], String> {
        Ok([self.f()?, self.f()?, self.f()?])
    }
    fn vec2(&mut self) -> Result<[f32; 2], String> {
        Ok([self.f()?, self.f()?])
    }
    fn part(&mut self) -> Result<Part, String> {
        let n = self.u()? as usize;
        // Indices are u32 end to end (`Part::indices`, the GPU's
        // `IndexFormat::Uint32`), so the old 65,535 ceiling was the client's
        // u16 index width surviving as a refusal: any SpeedTree component
        // heavier than it silently lost its whole tree type. The ceiling now
        // only stops a damaged count reserving memory, and it is named so a
        // component that really is this heavy reports itself.
        if n > MAX_TREE_VERTICES {
            return Err(format!(
                "tree vertex limit: {n} vertices in one component (limit {MAX_TREE_VERTICES})"
            ));
        }
        let mut vertices = Vec::with_capacity(n);
        for _ in 0..n {
            vertices.push(Vert {
                pos: self.vec3()?,
                normal: self.vec3()?,
                uv: self.vec2()?,
            })
        }
        let n = self.u()? as usize;
        if n > 3_000_000 || n % 3 != 0 {
            return Err("tree index limit".into());
        }
        let mut indices = Vec::with_capacity(n);
        for _ in 0..n {
            let i = self.u()?;
            if i as usize >= vertices.len() {
                return Err("tree index out of range".into());
            }
            indices.push(i)
        }
        Ok(Part { vertices, indices })
    }
}
/// The `__IdvSpt_0N_` tag of one source, if it carries one.
///
/// A source without the tag is not a SpeedTree file at all; that is the loader's
/// problem (`parse` will reject the cache built from it), so nothing is said
/// here.
fn source_tag(bytes: &[u8]) -> Option<String> {
    crate::speedtree_version::spt_tag(bytes)
}

/// Normalise a tree asset name for pack lookup.
///
/// The world file writes `Trees\\Elm\\Elm.spt`; the pack may hold
/// `trees/elm/elm.SPT`. Both separators collapse to `/` and the whole name is
/// lower-cased, which matches what the pack reader's own lookups do.
fn normalise_tree_name(name: &str) -> String {
    name.replace('\\', "/").to_lowercase()
}

/// The nearest `trees.pck` names to one that was asked for and not found.
///
/// A missing name on its own cannot be acted on: the reader knows the pack, so
/// it names what the pack actually holds that is closest by shared path tail.
/// The stem and the file name are both tried because clients disagree about the
/// folder.
fn nearest_tree_names(entries: &HashMap<String, pck::Entry>, wanted: &str) -> String {
    let stem = wanted.rsplit('/').next().unwrap_or(wanted);
    let mut hits: Vec<&String> = entries
        .keys()
        .filter(|name| {
            let tail = name.rsplit('/').next().unwrap_or(name.as_str());
            // Same file name in another folder, or the same base name with a
            // different extension.
            name.ends_with(stem)
                || stem.ends_with(tail)
                || match (tail.rsplit_once('.'), stem.rsplit_once('.')) {
                    (Some((a, _)), Some((b, _))) => a == b,
                    _ => false,
                }
        })
        .collect();
    // Fall back to a common stem so a differently-foldered tree still shows up.
    if hits.is_empty() {
        let root = stem.split('.').next().unwrap_or(stem);
        hits = entries
            .keys()
            .filter(|name| name.contains(root))
            .collect::<Vec<_>>();
    }
    hits.sort();
    hits.truncate(5);
    if hits.is_empty() {
        format!(
            "trees.pck holds {} entries and none share that name; check the map's tree table",
            entries.len()
        )
    } else {
        format!("nearest names in trees.pck: {hits:?}")
    }
}

/// Vertices allowed in one SpeedTree component.
///
/// The authored components in shipped `trees.pck` files are small, but the
/// reader must not be the reason a heavier one disappears; indices are u32, so
/// the only real bound is memory. Four million vertices is a 200 MB reservation
/// at worst, which a damaged length word should not be allowed to trigger.
const MAX_TREE_VERTICES: usize = 4_000_000;

fn parse(d: &[u8], source: &[u8], dll_hash: u32) -> Result<(String, Vec<TreeLod>), String> {
    let mut r = Reader { d, p: 0 };
    let magic = r.take(8)?;
    let (animated, native_alpha_refs, leaf_normals) = match magic {
        b"PWTREE05" => (false, false, false),
        b"PWTREE06" | b"PWTREE07" => (true, false, false),
        b"PWTREE08" => (true, true, false),
        b"PWTREE09" => (true, true, true),
        _ => return Err("unknown tree cache version".into()),
    };
    if r.u()? != dll_hash {
        return Err("tree cache runtime mismatch: rebake".into());
    }
    let mut hash = 2166136261u32;
    for b in source {
        hash = (hash ^ u32::from(*b)).wrapping_mul(16777619);
    }
    if r.u()? != hash {
        return Err("tree cache source mismatch: rebake".into());
    }
    let n = r.u()? as usize;
    if n > 4096 {
        return Err("tree texture name too long".into());
    }
    let (name, _, bad) = encoding_rs::GBK.decode(r.take(n)?);
    if bad {
        return Err("invalid tree texture name".into());
    }
    let count = r.u()? as usize;
    if count != 3 {
        return Err("unsupported tree LOD count".into());
    }
    let mut lods = Vec::with_capacity(count);
    for _ in 0..count {
        let branch = r.part()?;
        let frond = r.part()?;
        let (branch_alpha_ref, frond_alpha_ref) = if native_alpha_refs {
            let branch_ref = r.f()?;
            let frond_ref = r.f()?;
            if !(-1.0..=255.0).contains(&branch_ref) || !(-1.0..=255.0).contains(&frond_ref) {
                return Err("invalid native tree alpha reference".into());
            }
            (Some(branch_ref), Some(frond_ref))
        } else {
            (None, None)
        };
        let n = r.u()? as usize;
        if n > 65535 {
            return Err("tree leaf limit".into());
        }
        let mut leaves = Vec::with_capacity(n);
        for _ in 0..n {
            let center = r.vec3()?;
            let normal = if leaf_normals { Some(r.vec3()?) } else { None };
            let rho = r.f()?;
            let mut corners = [[0.; 3]; 4];
            let mut uv = [[0.; 2]; 4];
            for i in 0..4 {
                corners[i] = r.vec3()?;
                uv[i] = r.vec2()?;
            }
            let cluster = if animated { r.u()? } else { 0 };
            leaves.push(Leaf {
                center,
                normal,
                rho,
                corners,
                uv,
                cluster,
            })
        }
        let (rocking_clusters, rocking) = if animated {
            let clusters = r.u()? as usize;
            let frames = r.u()? as usize;
            if clusters > 512
                || frames != 64
                || leaves.iter().any(|l| l.cluster as usize >= clusters)
            {
                return Err("invalid tree rocking data".into());
            }
            let mut samples = Vec::with_capacity(clusters * 4 * frames);
            for _ in 0..clusters * 4 * frames {
                samples.push(r.vec3()?);
            }
            (clusters, samples)
        } else {
            (0, Vec::new())
        };
        lods.push(TreeLod {
            branch,
            frond,
            branch_alpha_ref,
            frond_alpha_ref,
            leaves,
            rocking,
            rocking_clusters,
        });
    }
    if r.p != d.len() {
        return Err("trailing tree cache bytes".into());
    }
    Ok((name.into_owned(), lods))
}
impl Trees {
    pub fn open(element: &Path, scene: &scene::Scene, cache: &Path) -> Result<Self, String> {
        let placements = scene
            .blocks
            .iter()
            .flat_map(|b| b.trees.iter().cloned())
            .collect();
        // Some instance maps ship no SpeedTree table at all. Do not require the
        // 32-bit DLL, trees.pck or a baked cache for an empty type table.
        if scene.tree_types.is_empty() {
            return Ok(Self {
                types: Vec::new(),
                placements,
                off_reason: None,
            });
        }
        let mut types: Vec<Option<TreeMesh>> = (0..scene.tree_types.len()).map(|_| None).collect();
        if !cache.is_dir() {
            let reason = format!("Trees off: no SpeedTree cache at {}", cache.display());
            eprintln!("{reason} (see README)");
            return Ok(Self {
                types,
                placements,
                off_reason: Some(reason),
            });
        }
        let mut dll_file = match File::open(element.join("speedtreert.dll")) {
            Ok(file) => file,
            Err(e) => {
                let reason = format!(
                    "Trees off: cannot open {}/speedtreert.dll: {e}",
                    element.display()
                );
                eprintln!("{reason}");
                return Ok(Self {
                    types,
                    placements,
                    off_reason: Some(reason),
                });
            }
        };
        let mut dll_hash = 2166136261u32;
        let mut buf = [0u8; 65536];
        // The DLL's own bytes carry two things the reader wants: the cache key
        // hash, and the `__IdvSpt_0N_` tag it accepts. The first 4 KiB hold the
        // PE header and the tag, so the head is kept while the whole file is
        // still hashed exactly as before (the cache key must not change).
        let mut dll_head: Vec<u8> = Vec::new();
        loop {
            let n = dll_file
                .read(&mut buf)
                .map_err(|e| format!("SpeedTreeRT.dll: {e}"))?;
            if n == 0 {
                break;
            }
            if dll_head.len() < 4096 {
                let take = (4096 - dll_head.len()).min(n);
                dll_head.extend_from_slice(&buf[..take]);
            }
            for &byte in &buf[..n] {
                dll_hash = (dll_hash ^ u32::from(byte)).wrapping_mul(16777619);
            }
        }
        let mut file = match File::open(element.join("trees.pck")) {
            Ok(file) => file,
            Err(e) => {
                let reason = format!(
                    "Trees off: cannot open {}/trees.pck: {e}",
                    element.display()
                );
                eprintln!("{reason}");
                return Ok(Self {
                    types,
                    placements,
                    off_reason: Some(reason),
                });
            }
        };
        // Tree names come from the world file with `\` separators and mixed
        // case, and `trees.pck` entries may use either separator, so both sides
        // are normalised to `/` and ASCII lower case before comparison. Matching
        // on the raw text is why a tree could be present in the pack and still
        // report "missing SPT".
        let entries: HashMap<String, pck::Entry> = pck::directory(&mut file)?
            .into_iter()
            .map(|e| (normalise_tree_name(&e.name), e))
            .collect();
        // Read once, before any type is loaded: the tag the runtime accepts.
        // A DLL that is not a 32-bit PE is refused here by name rather than
        // failing later in `Command::new` with a loader error.
        if let Err(e) =
            crate::speedtree_version::check_dll(crate::speedtree_version::pe_machine(&dll_head))
        {
            eprintln!("SpeedTree: {e}; trees are kept and will report the runtime's own error");
        }
        let dll_tag = crate::speedtree_version::dll_tag(&dll_head);
        let versions_reported = AtomicUsize::new(0);
        let load_one = |i: usize| -> Result<TreeMesh, String> {
            let ty = &scene.tree_types[i];
            let data =
                fs::read(cache.join(format!("tree-{i:03}.pwt"))).map_err(|e| e.to_string())?;
            let wanted = normalise_tree_name(&ty.tree);
            let src = entries.get(&wanted).ok_or_else(|| {
                format!(
                    "missing SPT: asked trees.pck for {wanted:?}; {}",
                    nearest_tree_names(&entries, &wanted)
                )
            })?;
            let original = pck::read_entry_at(&file, src).map_err(|e| e.to_string())?;
            // The version question is asked of every source, and answered the
            // same way each time: a mismatch is named and the tree is kept.
            // Only the first few are printed, or a 59-type map would bury the
            // log; the count is printed once afterwards.
            if let Some(warning) = crate::speedtree_version::tag_warning(
                dll_tag.as_deref(),
                source_tag(&original).as_deref(),
            ) {
                let seen = versions_reported.fetch_add(1, Ordering::Relaxed);
                if seen < 3 {
                    eprintln!("Tree type {i}: {warning}");
                }
            }
            let (name, lods) = parse(&data, &original, dll_hash)?;
            let name = name.replace('\\', "/");
            let stem = Path::new(&name)
                .file_stem()
                .and_then(|s| s.to_str())
                .ok_or("missing bark name")?;
            let parent = ty.tree.rsplit_once('/').map(|x| x.0).unwrap_or("trees");
            let bark_path = format!("{parent}/{stem}.dds").to_lowercase();
            let fallback = format!("trees/{stem}.dds").to_lowercase();
            let bark_entry = entries
                .get(&normalise_tree_name(&bark_path))
                .or_else(|| entries.get(&normalise_tree_name(&fallback)))
                .ok_or_else(|| format!("branch material: missing bark texture {bark_path}"))?;
            let want_composite = normalise_tree_name(&ty.composite);
            let tex_entry = entries.get(&want_composite).ok_or_else(|| {
                format!(
                    "frond/leaf material: missing composite texture {want_composite:?}; {}",
                    nearest_tree_names(&entries, &want_composite)
                )
            })?;
            let bark_bytes = pck::read_entry_at(&file, bark_entry)
                .map_err(|e| format!("branch material texture {}: {e}", bark_entry.name))?;
            let tex_bytes = pck::read_entry_at(&file, tex_entry)
                .map_err(|e| format!("frond/leaf material texture {}: {e}", tex_entry.name))?;
            let bark = image::load_from_memory_with_format(&bark_bytes, image::ImageFormat::Dds)
                .map_err(|e| format!("branch material texture {}: {e}", bark_entry.name))?
                .to_rgba8();
            let composite =
                image::load_from_memory_with_format(&tex_bytes, image::ImageFormat::Dds)
                    .map_err(|e| format!("frond/leaf material texture {}: {e}", tex_entry.name))?
                    .to_rgba8();
            let bark_mips = crate::vegetation_textures::authored_lower_mips(&bark_bytes)
                .unwrap_or_else(|e| {
                    eprintln!("Tree type {i} bark authored mips unavailable: {e}");
                    Vec::new()
                });
            let composite_mips = crate::vegetation_textures::authored_lower_mips(&tex_bytes)
                .unwrap_or_else(|e| {
                    eprintln!("Tree type {i} composite authored mips unavailable: {e}");
                    Vec::new()
                });
            Ok(TreeMesh {
                lods,
                bark,
                composite,
                bark_mips,
                composite_mips,
            })
        };
        let workers = if scene.tree_types.len() > 1 {
            std::thread::available_parallelism()
                .map(|n| n.get())
                .unwrap_or(1)
                .min(scene.tree_types.len())
        } else {
            1
        };
        let results: Vec<Result<TreeMesh, String>> = if workers > 1 {
            let chunk_size = scene.tree_types.len().div_ceil(workers);
            std::thread::scope(|s| {
                let handles: Vec<_> = (0..scene.tree_types.len())
                    .step_by(chunk_size)
                    .map(|start| {
                        let end = (start + chunk_size).min(scene.tree_types.len());
                        let load = &load_one;
                        s.spawn(move || (start..end).map(load).collect::<Vec<_>>())
                    })
                    .collect();
                handles
                    .into_iter()
                    .flat_map(|h| h.join().unwrap())
                    .collect()
            })
        } else {
            (0..scene.tree_types.len()).map(&load_one).collect()
        };
        let mut count = 0;
        for ((i, ty), result) in scene.tree_types.iter().enumerate().zip(results) {
            match result {
                Ok(mesh) => {
                    types[i] = Some(mesh);
                    count += 1;
                }
                Err(e) => eprintln!("Tree type {i} ({}): {e}", ty.tree),
            }
        }
        let mismatched = versions_reported.load(Ordering::Relaxed);
        if mismatched > 0 {
            eprintln!(
                "SpeedTree version: {mismatched} of {} source(s) disagreed with the runtime's tag; \
                 trees kept and the runtime decides",
                types.len()
            );
        }
        eprintln!(
            "Loaded {count}/{} SpeedTree types from runtime cache",
            types.len()
        );
        // A map can have a cache, a DLL and a pack and still draw nothing,
        // because every name in its tree table missed. That case gets the same
        // visible reason as the others, with the names the pack does hold.
        let off_reason = if count == 0 && !scene.tree_types.is_empty() {
            Some(format!(
                "Trees off: none of the {} tree names in this map's table were found; first is {:?}",
                scene.tree_types.len(),
                scene.tree_types[0].tree
            ))
        } else {
            None
        };
        Ok(Self {
            types,
            placements,
            off_reason,
        })
    }
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn accepts_three_empty_lods_and_checks_hashes() {
        let source = b"asset";
        let mut hash = 2166136261u32;
        for b in source {
            hash = (hash ^ u32::from(*b)).wrapping_mul(16777619);
        }
        let mut b = b"PWTREE05".to_vec();
        b.extend_from_slice(&42u32.to_le_bytes());
        b.extend_from_slice(&hash.to_le_bytes());
        b.extend_from_slice(&0u32.to_le_bytes());
        b.extend_from_slice(&3u32.to_le_bytes());
        for _ in 0..3 {
            for _ in 0..5 {
                b.extend_from_slice(&0u32.to_le_bytes());
            }
        }
        assert_eq!(parse(&b, source, 42).unwrap().1.len(), 3);
        assert!(parse(&b, source, 43).is_err());
        assert!(parse(&b, b"other", 42).is_err());
        assert!(parse(&b[..b.len() - 1], source, 42).is_err());
    }
    #[test]
    fn reads_native_alpha_references_only_from_pwtree08() {
        let source = b"tree";
        let mut hash = 2166136261u32;
        for b in source {
            hash = (hash ^ u32::from(*b)).wrapping_mul(16777619);
        }
        let mut b = b"PWTREE08".to_vec();
        for value in [42u32, hash, 0, 3] {
            b.extend_from_slice(&value.to_le_bytes());
        }
        for _ in 0..3 {
            // Empty branch and frond parts.
            for _ in 0..4 {
                b.extend_from_slice(&0u32.to_le_bytes());
            }
            b.extend_from_slice(&84f32.to_le_bytes());
            b.extend_from_slice(&255f32.to_le_bytes());
            // No leaves, then a valid empty 64-frame rocking table.
            for value in [0u32, 0, 64] {
                b.extend_from_slice(&value.to_le_bytes());
            }
        }
        let lods = parse(&b, source, 42).unwrap().1;
        assert_eq!(lods.len(), 3);
        assert_eq!(lods[0].branch_alpha_ref, Some(84.));
        assert_eq!(lods[0].frond_alpha_ref, Some(255.));
        assert!(parse(&b[..b.len() - 1], source, 42).is_err());
        let mut invalid = b;
        let ref_offset = 8 + 4 * 4 + 4 * 4;
        invalid[ref_offset..ref_offset + 4].copy_from_slice(&256f32.to_le_bytes());
        assert!(parse(&invalid, source, 42).is_err());
    }
    #[test]
    fn accepts_sampled_rocking_and_rejects_invalid_cluster() {
        let source = b"x";
        let hash = (2166136261u32 ^ u32::from(source[0])).wrapping_mul(16777619);
        let mut b = b"PWTREE06".to_vec();
        for value in [42u32, hash, 0, 3] {
            b.extend_from_slice(&value.to_le_bytes());
        }
        for _ in 0..3 {
            for value in [0u32, 0, 0, 0, 1] {
                b.extend_from_slice(&value.to_le_bytes());
            }
            for _ in 0..24 {
                b.extend_from_slice(&0f32.to_le_bytes());
            }
            b.extend_from_slice(&0u32.to_le_bytes());
            b.extend_from_slice(&1u32.to_le_bytes());
            b.extend_from_slice(&64u32.to_le_bytes());
            for frame in 0..4 * 64 {
                for v in [frame as f32, 0., 0.] {
                    b.extend_from_slice(&v.to_le_bytes());
                }
            }
        }
        let parsed = parse(&b, source, 42).unwrap().1;
        assert_eq!(parsed[0].rocking.len(), 256);
        assert_eq!(parsed[0].rocking[4][0], 4.);
        let mut invalid = b.clone();
        let cluster_offset = 8 + 4 * 4 + 5 * 4 + 24 * 4;
        invalid[cluster_offset..cluster_offset + 4].copy_from_slice(&2u32.to_le_bytes());
        assert!(parse(&invalid, source, 42).is_err());
        assert!(parse(&b[..b.len() - 4], source, 42).is_err());
    }
    #[test]
    fn reads_per_leaf_normals_only_from_version_09() {
        let source = b"x";
        let hash = (2166136261u32 ^ u32::from(source[0])).wrapping_mul(16777619);
        for version in [b"PWTREE07", b"PWTREE09"] {
            let mut b = version.to_vec();
            for value in [42u32, hash, 0, 3] {
                b.extend_from_slice(&value.to_le_bytes());
            }
            for _ in 0..3 {
                for value in [0u32, 0, 0, 0] {
                    b.extend_from_slice(&value.to_le_bytes());
                }
                if version == b"PWTREE09" {
                    b.extend_from_slice(&84f32.to_le_bytes());
                    b.extend_from_slice(&84f32.to_le_bytes());
                }
                b.extend_from_slice(&1u32.to_le_bytes());
                for v in [1f32, 2., 3.] {
                    b.extend_from_slice(&v.to_le_bytes());
                }
                if version == b"PWTREE09" {
                    for v in [0.25f32, -0.5, 0.75] {
                        b.extend_from_slice(&v.to_le_bytes());
                    }
                }
                for _ in 0..21 {
                    b.extend_from_slice(&0f32.to_le_bytes());
                }
                for value in [0u32, 1, 64] {
                    b.extend_from_slice(&value.to_le_bytes());
                }
                for _ in 0..4 * 64 * 3 {
                    b.extend_from_slice(&0f32.to_le_bytes());
                }
            }
            let lods = parse(&b, source, 42).unwrap().1;
            assert_eq!(lods[0].leaves[0].center, [1., 2., 3.]);
            assert_eq!(
                lods[0].leaves[0].normal,
                if version == b"PWTREE09" {
                    Some([0.25, -0.5, 0.75])
                } else {
                    None
                }
            );
            assert!(parse(&b[..b.len() - 1], source, 42).is_err());
            if version == b"PWTREE09" {
                let normal_offset = 8 + 4 * 4 + 4 * 4 + 2 * 4 + 4 + 3 * 4;
                b[normal_offset..normal_offset + 4].copy_from_slice(&f32::NAN.to_le_bytes());
                assert!(parse(&b, source, 42).is_err());
            }
        }
    }
    #[test]
    fn reject_invalid() {
        assert!(parse(b"PWTREE05\0\0\0\0", b"x", 0).is_err());
        assert!(parse(b"garbage", b"", 0).is_err());
    }
}
